static unsigned u16(const unsigned char*p){return p[0]|((unsigned)p[1]<<8);}
static uint32_t u32(const unsigned char*p){return p[0]|((uint32_t)p[1]<<8)|((uint32_t)p[2]<<16)|((uint32_t)p[3]<<24);}
static int at(struct ez_zip*z,uint32_t off,void*p,unsigned n){return off<=z->bytes&&n<=z->bytes-off&&!fseek(z->file,(long)off,SEEK_SET)&&fread(p,1,n,z->file)==n;}
uint32_t ez_crc(const unsigned char*p,unsigned n){uint32_t c=~0u;while(n--){c^=*p++;for(unsigned i=0;i<8;i++)c=(c>>1)^((c&1)?0xedb88320u:0);}return ~c;}
int ez_resolve(const char*base,const char*href,char out[256],char fragment[128]){char joined[768],decoded[512];unsigned n=0;fragment[0]=0;for(unsigned i=0;href[i]&&href[i]!='#';i++){unsigned char c=href[i];if(c=='%'){unsigned a=href[i+1],b=a?href[i+2]:0;a=a>='0'&&a<='9'?a-'0':a>='A'&&a<='F'?a-'A'+10:a>='a'&&a<='f'?a-'a'+10:99;b=b>='0'&&b<='9'?b-'0':b>='A'&&b<='F'?b-'A'+10:b>='a'&&b<='f'?b-'a'+10:99;if(a>15||b>15)return 0;c=(unsigned char)(a*16+b);i+=2;}if(!c||c=='\\'||c==':'||c=='?'||n>=sizeof decoded-1)return 0;decoded[n++]=(char)c;}decoded[n]=0;const char*f=strchr(href,'#');if(f){if(strlen(f+1)>=128)return 0;strcpy(fragment,f+1);}if(decoded[0]=='/')return 0;if(!n){if(strlen(base)>=256)return 0;strcpy(out,base);return 1;}const char*slash=strrchr(base,'/');unsigned prefix=slash?(unsigned)(slash-base+1):0;if(prefix+n>=sizeof joined)return 0;memcpy(joined,base,prefix);memcpy(joined+prefix,decoded,n+1);out[0]=0;unsigned used=0;char*p=joined;while(*p){char*q=strchr(p,'/');unsigned len=q?(unsigned)(q-p):(unsigned)strlen(p);if(!len||len==1&&p[0]=='.'){}else if(len==2&&p[0]=='.'&&p[1]=='.'){if(!used)return 0;while(used&&out[used-1]!='/')used--;if(used)used--;out[used]=0;}else{if(used+len+1>=256)return 0;if(used)out[used++]='/';memcpy(out+used,p,len);used+=len;out[used]=0;}if(!q)break;p=q+1;}return used>0;}
int ez_open(struct ez_zip*z,FILE*f,uint32_t bytes){memset(z,0,sizeof(*z));z->file=f;z->bytes=bytes;if(bytes<22)return 0;unsigned n=bytes<65557?bytes:65557;unsigned char*tail=malloc(n);if(!tail||!at(z,bytes-n,tail,n)){free(tail);return 0;}int e=-1;for(int i=(int)n-22;i>=0;i--)if(u32(tail+i)==0x06054b50&&i+22+u16(tail+i+20)==(int)n){e=i;break;}if(e<0){free(tail);return 0;}unsigned char*h=tail+e;uint32_t count=u16(h+10),size=u32(h+12),offset=u32(h+16);int ok=!u16(h+4)&&!u16(h+6)&&u16(h+8)==count&&count&&count<=4096&&offset<=bytes&&size<=bytes-offset;free(tail);if(!ok)return 0;z->entries=calloc(count,sizeof(*z->entries));if(!z->entries)return 0;z->count=count;uint32_t p=offset;for(unsigned i=0;i<count;i++){unsigned char head[46];if(!at(z,p,head,sizeof head)||u32(head)!=0x02014b50)goto fail;unsigned len=u16(head+28),extra=u16(head+30),comment=u16(head+32);if(!len||len>=256||u16(head+34)||p+46>offset+size||len+extra+comment>offset+size-(p+46))goto fail;struct ez_entry*r=z->entries+i;if(!at(z,p+46,r->name,len))goto fail;r->name[len]=0;if(memchr(r->name,0,len)||r->name[0]=='/'||strchr(r->name,'\\')||strchr(r->name,':'))goto fail;char normalized[256],frag[128];if(r->name[len-1]!='/'){if(!ez_resolve("",r->name,normalized,frag)||strcmp(normalized,r->name))goto fail;}for(unsigned j=0;j<i;j++)if(!strcmp(z->entries[j].name,r->name))goto fail;r->flags=u16(head+8);r->method=u16(head+10);r->crc=u32(head+16);r->compressed=u32(head+20);r->bytes=u32(head+24);r->offset=u32(head+42);if(r->offset>=bytes||r->compressed>bytes-r->offset||r->bytes>32*1024*1024)goto fail;p+=46+len+extra+comment;}return 1;fail:ez_close(z);return 0;}
void ez_close(struct ez_zip*z){free(z->entries);memset(z,0,sizeof(*z));}
int ez_find(const struct ez_zip*z,const char*name){for(unsigned i=0;i<z->count;i++)if(!strcmp(z->entries[i].name,name))return (int)i;return -1;}
unsigned char*ez_read(struct ez_zip*z,const char*name,unsigned limit,unsigned*out_size){int i=ez_find(z,name);if(i<0)return 0;struct ez_entry*r=z->entries+i;if(r->flags&1||r->bytes>limit||r->compressed>limit+65536||(r->method!=0&&r->method!=8))return 0;unsigned char h[30];if(!at(z,r->offset,h,30)||u32(h)!=0x04034b50||u16(h+8)!=r->method)return 0;uint32_t off=r->offset+30;if(off>z->bytes||u16(h+26)+u16(h+28)>z->bytes-off)return 0;unsigned name_len=u16(h+26);char local[256];if(name_len>=sizeof local||!at(z,off,local,name_len))return 0;local[name_len]=0;if(strcmp(local,name))return 0;off+=name_len+u16(h+28);if(off>z->bytes||r->compressed>z->bytes-off)return 0;unsigned char*out=malloc((size_t)r->bytes+1),*in=0;if(!out)return 0;if(r->method==0){if(r->compressed!=r->bytes||!at(z,off,out,r->bytes))goto fail;}else{in=malloc(r->compressed?r->compressed:1);if(!in||!at(z,off,in,r->compressed)||tinfl_decompress_mem_to_mem(out,r->bytes,in,r->compressed,0)!=r->bytes)goto fail;}free(in);if(ez_crc(out,r->bytes)!=r->crc){free(out);return 0;}out[r->bytes]=0;*out_size=r->bytes;return out;fail:free(in);free(out);return 0;}
